// Read-only stub of the private construction API for UI-only checks
// (construction-workbench.cjs without a backend). It serves the real web
// assets and one recorded problem view + geometry produced by the real
// compiler (construction-stub-fixture.json, regenerated by
// TestConstructionStubFixtureCurrent). Every mutation is refused: this stub
// proves layout, rendering and picking, never persistence or access control.
const fs = require('node:fs'), path = require('node:path'), http = require('node:http');
const web = path.join(__dirname, '../web');
const fx = JSON.parse(fs.readFileSync(path.join(__dirname, 'construction-stub-fixture.json'), 'utf8'));
const types = {'.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.png': 'image/png', '.woff2': 'font/woff2', '.json': 'application/json', '.webmanifest': 'application/manifest+json'};
const base = '/api/properties/' + fx.slug + '/construction';
function json(res, code, body) { res.writeHead(code, {'Content-Type': 'application/json'}); res.end(JSON.stringify(body)); }
function start() {
  const server = http.createServer((req, res) => {
    const p = new URL(req.url, 'http://x').pathname;
    if (p.startsWith('/api/')) {
      if (req.method !== 'GET') return json(res, 403, {kind: 'stub', error: 'stub mode is read-only'});
      if (p === base + '/session') return json(res, 200, {nonce: 'stub', principal: 'owner', subject: fx.view.context.subject, templates: ['roof-masonry-junction'], operations: [], capabilities: {}});
      if (p === base + '/problems') return json(res, 200, {problems: [{id: fx.problemId, title: fx.title, lifecycle: 'draft', alternatives: 1, inputs: 0}]});
      if (p === base + '/problems/' + fx.problemId) return json(res, 200, fx.view);
      if (p.startsWith(base + '/problems/' + fx.problemId + '/assemblies/' + fx.assemblyId + '/geometry')) return json(res, 200, fx.geometry);
      if (p === '/api/properties') return json(res, 200, {properties: [{slug: fx.slug, short: '1 Fixture Way', address: '1 Fixture Way, Testville, ZZ 00000', work: []}], deals: [], templates: [], holdings: {}});
      if (p === '/api/re/backlog') return json(res, 200, {items: [], goalsArea: null});
      if (p === '/api/tasks') return json(res, 200, {rows: [], domains: [], areas: [], counts: {}, outstanding: []});
      return json(res, 404, {error: 'not in the stub'});
    }
    const file = path.join(web, p === '/' ? 'index.html' : p);
    if (!file.startsWith(web) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); return res.end(); }
    res.writeHead(200, {'Content-Type': types[path.extname(file)] || 'application/octet-stream'});
    fs.createReadStream(file).pipe(res);
  });
  return new Promise((r) => server.listen(0, '127.0.0.1', () => r(server)));
}
module.exports = {start, slug: fx.slug, problemId: fx.problemId, title: fx.title, apronId: fx.apronId};
